from hypothesis import strategies as st


@st.composite
def gen(draw):
    n = draw(st.integers(2, 6))
    m = draw(st.integers(1, 9))
    x = draw(st.integers(1, 10))
    edges = []
    for _ in range(m):
        u = draw(st.integers(1, n))
        v = draw(st.integers(1, n))
        edges.append((u, v))
    # Guarantee the underlying undirected graph connects 1 and N
    # (flipping lets us traverse any edge in either direction).
    if draw(st.booleans()):
        edges.append((1, n))
    else:
        edges.append((n, 1))
    lines = [f"{n} {len(edges)} {x}"]
    for u, v in edges:
        lines.append(f"{u} {v}")
    return "\n".join(lines) + "\n"


def validate(inp):
    try:
        t = inp.split()
        if len(t) < 3:
            return False
        n, m, x = int(t[0]), int(t[1]), int(t[2])
        if not (2 <= n <= 2 * 10**5):
            return False
        if not (1 <= m <= 2 * 10**5):
            return False
        if not (1 <= x <= 10**9):
            return False
        if len(t) != 3 + 2 * m:
            return False
        parent = list(range(n + 1))

        def find(a):
            while parent[a] != a:
                parent[a] = parent[parent[a]]
                a = parent[a]
            return a

        for i in range(m):
            u = int(t[3 + 2 * i])
            v = int(t[4 + 2 * i])
            if not (1 <= u <= n and 1 <= v <= n):
                return False
            parent[find(u)] = find(v)
        # Reachability is guaranteed iff 1 and N are connected undirected.
        return find(1) == find(n)
    except Exception:
        return False


def ref(inp):
    t = inp.split()
    n, m, x = int(t[0]), int(t[1]), int(t[2])
    orig = []
    for i in range(m):
        u = int(t[3 + 2 * i]) - 1
        v = int(t[4 + 2 * i]) - 1
        orig.append((u, v))
    # State (vertex, flip parity). Parity 0: original orientation; 1: reversed.
    # Bellman-Ford relaxation over the 2N states until no change.
    INF = float("inf")
    S = 2 * n
    dist = [INF] * S
    dist[0 * 2 + 0] = 0  # vertex 0 (vertex 1), parity 0
    # Build explicit transitions.
    trans = []  # (from_state, to_state, cost)
    for (u, v) in orig:
        # parity 0: edge u->v usable when moving from u
        trans.append((u * 2 + 0, v * 2 + 0, 1))
        # parity 1: reversed edge v->u usable when moving from v
        trans.append((v * 2 + 1, u * 2 + 1, 1))
    for v in range(n):
        trans.append((v * 2 + 0, v * 2 + 1, x))
        trans.append((v * 2 + 1, v * 2 + 0, x))
    changed = True
    while changed:
        changed = False
        for a, b, c in trans:
            if dist[a] != INF and dist[a] + c < dist[b]:
                dist[b] = dist[a] + c
                changed = True
    ans = min(dist[(n - 1) * 2 + 0], dist[(n - 1) * 2 + 1])
    return str(ans)
