import heapq
from hypothesis import strategies as st
from hypothesis import assume


@st.composite
def gen(draw):
    n = draw(st.integers(2, 5))
    m = draw(st.integers(1, 8))
    x = draw(st.integers(1, 10))
    edges = []
    for _ in range(m):
        u = draw(st.integers(1, n))
        v = draw(st.integers(1, n))
        edges.append((u, v))
    # Reversals are free to use at cost X, so solvability is equivalent to
    # N being reachable from 1 in the underlying undirected graph.
    assume(_undirected_connected(n, edges))
    lines = [f"{n} {m} {x}"] + [f"{u} {v}" for u, v in edges]
    return "\n".join(lines) + "\n"


def _undirected_connected(n, edges):
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    seen = [False] * (n + 1)
    seen[1] = True
    stack = [1]
    while stack:
        c = stack.pop()
        for d in adj[c]:
            if not seen[d]:
                seen[d] = True
                stack.append(d)
    return seen[n]


def validate(inp):
    try:
        lines = inp.strip("\n").split("\n")
        n, m, x = map(int, lines[0].split())
        if not (2 <= n <= 2 * 10**5 and 1 <= m <= 2 * 10**5 and 1 <= x <= 10**9):
            return False
        if len(lines) != m + 1:
            return False
        edges = []
        for i in range(1, m + 1):
            parts = lines[i].split()
            if len(parts) != 2:
                return False
            u, v = int(parts[0]), int(parts[1])
            if not (1 <= u <= n and 1 <= v <= n):
                return False
            edges.append((u, v))
        return _undirected_connected(n, edges)
    except Exception:
        return False


def ref(inp):
    lines = inp.strip("\n").split("\n")
    n, m, x = map(int, lines[0].split())
    orig = []  # orig[a] = list of b with original edge a->b
    rev = []   # rev[b] = list of a with original edge a->b
    orig = [[] for _ in range(n + 1)]
    rev = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        orig[u].append(v)
        rev[v].append(u)
    # State (vertex, r): r = 0 means original orientation, r = 1 means reversed.
    # In state r=0: move along original edge v->u cost 1 (stay r=0).
    # In state r=1: move along reversed edge, i.e. original edge u->v gives v->u, cost 1.
    # Reversal toggles r at cost X, keeping the vertex.
    INF = float("inf")
    dist = [[INF, INF] for _ in range(n + 1)]
    dist[1][0] = 0
    pq = [(0, 1, 0)]
    while pq:
        d, v, r = heapq.heappop(pq)
        if d != dist[v][r]:
            continue
        nxt = []
        if r == 0:
            for u in orig[v]:
                nxt.append((d + 1, u, 0))
        else:
            for u in rev[v]:
                nxt.append((d + 1, u, 1))
        nxt.append((d + x, v, 1 - r))
        for nd, nv, nr in nxt:
            if nd < dist[nv][nr]:
                dist[nv][nr] = nd
                heapq.heappush(pq, (nd, nv, nr))
    return str(min(dist[n][0], dist[n][1]))
